local _, WFJ = ...
WFJ.Data.add("book", {
  ["27188a14c98b8c17"] = { "Giorno 15\nLa nostra dedizione è stata ripagata. Siamo il primo accampamento a completare la costruzione di una pietra del vento. Se quegli altri sciocchi fossero rimasti con noi, avremmo finito il lavoro in meno di una settimana!\n\nDomani inizieremo i rituali necessari per evocare il barone Kazum in persona. Ha preteso di essere il primo a provare il sistema e non abbiamo potuto contraddirlo, perché si adira facilmente.\n\nMi aspetto che sarà molto soddisfatto di noi.", "." },
  ["271b43dbef66b7c9"] = { "Iniziai i miei esperimenti partendo dal presupposto che la sanguinite fosse un tipo di roccia, come il quarzo o l'ossidiana. Avviai quindi una serie di procedure per determinare quali minerali contenesse la sanguinite, quali forze fossero intervenute a darle colore e durezza, e altre proprietà comuni a rocce e minerali grezzi. Ma il pendente di sanguinite, con mia grande frustrazione, non reagì alle procedure come avrebbe fatto un normale minerale.", "." },
  ["2728331127417a82"] = { "Quando mi è giunta voce che il tuo momento era arrivato, ti ho mandato subito questo sigillo. Tutti i druidi di Cenarius provano grande soddisfazione nel vedere crescere il nostro numero. Persino gli spiriti sembrano essersi rafforzati con la nostra accresciuta presenza. Col tempo, e con un po' di pazienza, speriamo che la nostra forza torni all'antica grandezza. Cercami vicino alla cima di Aldrassil quando te la senti. Sarò la tua guida finché resterai a ⟦Shadowglen=Vallombra⟧.\n\n- ⟦Mardant Strongoak=Mardant Aspraquercia⟧, istruttore dei druidi", "." },
  ["273b2dd8223a91a2"] = { "I possenti draghi, che erano fuggiti davanti all'inarrestabile avanzata delle società mortali, si trovarono a combattere ad armi troppo pari contro le magie oscure della Legione. Aegwynn affrontò i demoni e, con l'aiuto dei nobili draghi, li annientò. Eppure, mentre l'ultimo demone veniva bandito dal mondo mortale, una grande tempesta si scatenò in tutto il nord.", "." },
  ["2742b90d3be34707"] = { "Della buona quercia scorzasecca - Prima che venissero occupate, le miniere sotto ⟦Moonbrook=Rivoluna⟧, nelle ⟦Westfall=Marche Occidentali⟧, ne avevano in abbondanza: la usavano per costruire alcune delle loro impalcature e dei loro attrezzi più importanti, perché resiste bene al calore e alla pressione.\n\nLaggiù era stata portata dopo essere arrivata via nave da qualche parte oltremare. È un legno raro, più che abbastanza robusto per essere usato nella creazione della tua arma. Se nelle miniere ne è rimasto un po', ce l'avranno gli intagliatori goblin.", "." },
  ["27b66c097d40fe4c"] = { "Da diffondere immediatamente a tutti i membri del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.\n\nLe informazioni che seguono descrivono l'uso delle pietre del vento per comunicare con i nostri padroni dell'Abyssal Council.\n\nOgni uso frivolo delle pietre del vento sarà punito nel modo più doloroso.\n\n-⟦Twilight Keeper Havunth=Protettore del Crepuscolo Havunth⟧", "." },
})
